'use strict';
const WEEKLY_QUESTIONS=[
 {id:'thoughts',label:'Thoughts looping',question:'How often did the same worries or thoughts keep looping?',kind:'difficulty'},
 {id:'avoidance',label:'Putting things off',question:'How often did you avoid something that mattered because it felt uncomfortable?',kind:'difficulty'},
 {id:'connection',label:'Feeling disconnected',question:'How often did you feel disconnected from other people?',kind:'difficulty'},
 {id:'overload',label:'Feeling overloaded',question:'How often did everyday demands feel like too much?',kind:'difficulty'},
 {id:'selftalk',label:'Harsh self-talk',question:'How often were you hard on yourself after a difficult moment?',kind:'difficulty'},
 {id:'rest',label:'Rest that helped',question:'How often did rest or sleep leave you feeling restored?',kind:'support'},
 {id:'needs',label:'Noticing your needs',question:'How often did you notice what you needed and make some room for it?',kind:'support'},
 {id:'action',label:'Meaningful small steps',question:'How often did you take a small step toward something that mattered to you?',kind:'support'}
];
const WEEKLY_CHOICES=['Not this week','1–2 days','3–4 days','5–7 days'];
const weeklyNav=$('#space-drawer nav');weeklyNav.insertAdjacentHTML('beforeend',`<a href="#weekly">${catSymbol()}<span>Weekly reflection</span></a><a href="#patterns">${catSymbol()}<span>Patterns & garden</span></a>`);
let weeklyDraft=null,weeklyIndex=0,weeklyMetric='thoughts',weeklyFilter='all',weeklyViewWeek=null;
function ensureWeekly(){if(!Array.isArray(state.weekly))state.weekly=[];return state.weekly;}
function localWeekKey(date=new Date()){const d=new Date(date);d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function weeklyDate(key){const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d,12);}
function weekLabel(key){return weeklyDate(key).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function weeklySeries(records,metric){return records.slice().sort((a,b)=>a.week.localeCompare(b.week)).slice(-8).map(r=>({week:r.week,value:Number.isInteger(r.answers[metric])?r.answers[metric]:null}));}
function weeklyPatterns(records){const rows=records.slice().sort((a,b)=>a.week.localeCompare(b.week)).slice(-4);if(rows.length<3)return [];return WEEKLY_QUESTIONS.flatMap(q=>{const answered=rows.filter(r=>Number.isInteger(r.answers[q.id]));if(answered.length<3)return [];const repeated=answered.filter(r=>r.answers[q.id]>=2);if(repeated.length<2)return [];return [{id:q.id,label:q.label,kind:q.kind,count:repeated.length,total:answered.length,text:`You selected 3–7 days for “${q.label.toLowerCase()}” in ${repeated.length} of your last ${answered.length} completed weekly reflections.`}];});}
function startWeekly(){const existing=ensureWeekly().find(r=>r.week===localWeekKey());weeklyDraft=existing?JSON.parse(JSON.stringify(existing)):{id:crypto.randomUUID(),week:localWeekKey(),date:stamp(),answers:{},note:'',situation:'',response:'',need:''};weeklyIndex=0;weeklyViewWeek=null;}
function weeklyPage(){const existing=ensureWeekly().find(r=>r.week===(weeklyViewWeek||localWeekKey()));if(!weeklyDraft)return `<div class="weekly-intro narrow"><div class="weekly-cat">${catSymbol()}</div><p class="eyebrow">A MOMENT, ONCE A WEEK</p><h1>A little look back.</h1><p>A few questions about your week. Skip anything.</p><div class="weekly-invitation"><span>${existing?'Your reflection for the week of '+weekLabel(existing.week):'A new reflection is ready for the week of '+weekLabel(localWeekKey())}</span><button class="primary" data-weekly="start">${existing?'Review this week':'Take a few minutes'} →</button></div><details class="reflection-about"><summary>About these questions</summary><p class="small">Original self-reflection prompts, not a clinical test or trauma assessment.</p></details><div class="actions"><a class="text-link" href="#patterns">See my patterns & garden →</a><a class="text-link" href="#explore">Explore a familiar reaction →</a></div></div>`;
 if(weeklyIndex<WEEKLY_QUESTIONS.length){const q=WEEKLY_QUESTIONS[weeklyIndex],answer=weeklyDraft.answers[q.id];return `<div class="weekly-flow narrow"><div class="weekly-flow-top"><a class="text-link" href="#chat">← Back to chat</a><button class="quiet-button" data-weekly="pause">Pause reflection</button></div><div class="step-track" aria-hidden="true">${WEEKLY_QUESTIONS.map((_,i)=>`<span class="${i<=weeklyIndex?'on':''}"></span>`).join('')}</div><p class="eyebrow">PAST SEVEN DAYS · ${weeklyIndex+1} OF ${WEEKLY_QUESTIONS.length}</p><h1>${q.question}</h1><div class="weekly-choices" role="group" aria-label="How often">${WEEKLY_CHOICES.map((label,i)=>`<button data-weekly-answer="${i}" aria-pressed="${answer===i}">${label}</button>`).join('')}</div><div class="actions"><button class="primary" data-weekly="next">${Number.isInteger(answer)?'Continue':'Skip this question'} →</button>${weeklyIndex?'<button class="secondary" data-weekly="back">Back</button>':''}${Number.isInteger(answer)?'<button class="quiet-button" data-weekly="skip">Prefer not to answer</button>':''}</div><p class="small">No detail is required. You can stop at any point. An unfinished reflection stays only in this tab until saved.</p></div>`;}
 return `<div class="weekly-review narrow"><p class="eyebrow">YOUR WEEK, IN YOUR WORDS</p><h1>What would you like to carry forward?</h1><div class="weekly-response-grid">${WEEKLY_QUESTIONS.map(q=>`<div><span>${q.label}</span><strong>${Number.isInteger(weeklyDraft.answers[q.id])?WEEKLY_CHOICES[weeklyDraft.answers[q.id]]:'Skipped'}</strong></div>`).join('')}</div><label for="weekly-note">Anything you noticed? (optional)</label><textarea id="weekly-note" maxlength="3000" placeholder="A situation, a need, or one thing that helped…">${esc(weeklyDraft.note)}</textarea><div class="actions"><button class="primary" data-weekly="finish">Save my week ${catSymbol()}</button><button class="secondary" data-weekly="back">Back</button></div><p class="small">One garden stamp per week, regardless of answers. No lost streaks. Saved using your current private-storage setting.</p></div>`;}
function saveWeeklyReflection(){if(!weeklyDraft)return;const note=$('#weekly-note');if(note)weeklyDraft.note=note.value;const rows=ensureWeekly(),at=rows.findIndex(r=>r.week===weeklyDraft.week),saved={...weeklyDraft,date:stamp()};if(at>=0)rows[at]=saved;else rows.push(saved);weeklyDraft=null;save();location.hash='patterns';toast('Your week is saved. One small moment counts.');}
function weeklyChartHTML(series){if(!series.some(x=>x.value!==null))return '<div class="chart-empty">Your own answers will appear here. No sample scores or invented history.</div>';const w=Math.min(640,Math.max(280,$('#main').clientWidth||640)),h=210,pad=35,days=86400000,first=weeklyDate(series[0].week).getTime(),last=weeklyDate(series.at(-1).week).getTime(),span=Math.max((last-first)/days,7),x=key=>pad+((weeklyDate(key).getTime()-first)/days)/span*(w-pad*2),y=v=>h-35-v*48;let lines='';for(let i=1;i<series.length;i++){const a=series[i-1],b=series[i];if(a.value!==null&&b.value!==null&&(weeklyDate(b.week)-weeklyDate(a.week))/days<=8)lines+=`<line x1="${x(a.week)}" y1="${y(a.value)}" x2="${x(b.week)}" y2="${y(b.value)}" stroke="#7a9382" stroke-width="2.5"/>`;}
 const stride=Math.max(1,Math.ceil(series.length/(w<420?4:8))),ticks=series.map((_,i)=>i).filter(i=>i%stride===0);if(ticks.at(-1)!==series.length-1){if(series.length-1-ticks.at(-1)<stride)ticks.pop();ticks.push(series.length-1);}const summary=series.map(r=>weekLabel(r.week)+': '+(r.value===null?'skipped':WEEKLY_CHOICES[r.value])).join('; ');return `<svg class="weekly-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(summary)}">${[0,1,2,3].map(v=>`<line x1="${pad}" x2="${w-pad}" y1="${y(v)}" y2="${y(v)}" stroke="#dfd8ce" stroke-width="1"/><text x="10" y="${y(v)+4}" fill="#6e665f" font-size="11">${v}</text>`).join('')}${lines}${series.map((r,index)=>`<g><title>${esc(weekLabel(r.week)+': '+(r.value===null?'Skipped':WEEKLY_CHOICES[r.value]))}</title>${r.value===null?`<text x="${x(r.week)}" y="${h-31}" text-anchor="middle" fill="#6e665f" font-size="13">–</text>`:`<circle cx="${x(r.week)}" cy="${y(r.value)}" r="5" fill="#7a9382"/>`}${ticks.includes(index)?`<text x="${x(r.week)}" y="${h-8}" text-anchor="middle" fill="#6e665f" font-size="11">${esc(weekLabel(r.week))}</text>`:''}</g>`).join('')}</svg><div class="chart-key">0 = not this week · 1 = 1–2 days · 2 = 3–4 days · 3 = 5–7 days</div><details class="chart-data"><summary>Read the exact answers</summary><ul>${series.map(r=>`<li>${weekLabel(r.week)}: ${r.value===null?'Skipped':WEEKLY_CHOICES[r.value]}</li>`).join('')}</ul></details>`;}
function gardenHTML(records){const weeks=[...new Set(records.map(r=>r.week))].sort();return `<div class="reflection-garden" aria-label="${weeks.length} weekly garden stamps"><div class="garden-ground"></div>${weeks.slice(-12).map((key,i)=>`<div class="garden-stamp" style="--order:${i}" title="Week of ${esc(weekLabel(key))}"><span class="garden-stem"></span><span class="garden-leaf leaf-left"></span><span class="garden-leaf leaf-right"></span><span class="garden-bloom">${catSymbol()}</span><small>${weekLabel(key)}</small></div>`).join('')}${weeks.length?'':'<p>Your garden starts with one weekly reflection.</p>'}</div><p class="small">One stamp for showing up, not for feeling better or sharing more. Missed weeks never remove a stamp.</p>`;}
function patternsPage(){const rows=ensureWeekly(),metric=WEEKLY_QUESTIONS.find(q=>q.id===weeklyMetric)||WEEKLY_QUESTIONS[0],series=weeklySeries(rows,metric.id),patterns=weeklyPatterns(rows),latest=rows.slice().sort((a,b)=>a.week.localeCompare(b.week)).at(-1),unique=new Set(rows.map(r=>r.week)).size;return `<div class="patterns-heading"><div><p class="eyebrow">CURIOUS, NOT JUDGMENTAL</p><h1>Your patterns, gently.</h1></div><a class="primary" href="#weekly">Weekly reflection →</a></div><div class="reflection-stats"><div><strong>${unique}</strong><span>weekly stamps</span></div><div><strong>${state.entries.length}</strong><span>journal pages</span></div><div><strong>${state.plans.filter(p=>p.done).length}</strong><span>small steps reviewed</span></div></div><section class="pattern-section"><div class="pattern-section-title"><h2>A growing little garden.</h2><span class="garden-label">No streak to protect.</span></div>${gardenHTML(rows)}</section><section class="pattern-section"><div class="pattern-section-title"><h2>What changes over time?</h2><label class="sr-only" for="weekly-metric">Pattern to view</label><select id="weekly-metric">${WEEKLY_QUESTIONS.map(q=>`<option value="${q.id}" ${q.id===weeklyMetric?'selected':''}>${q.label}</option>`).join('')}</select></div>${weeklyChartHTML(series)}<p class="small">Your reported frequency, not a severity score or diagnosis. Skipped answers and missed weeks stay missing. ${metric.kind==='support'?'This question tracks something supportive.':'This question tracks a difficulty.'}</p></section><section class="pattern-section"><h2>Things that may be worth noticing.</h2>${patterns.length?patterns.map(p=>`<div class="pattern-observation"><span>${catSymbol()}</span><div><h3>${p.label}</h3><p>${esc(p.text)}</p><small>${p.kind==='support'?'A possible source of support.':'A recurring experience to explore, not a label or cause.'}</small></div></div>`).join(''):'<p class="small">Patterns appear after three completed weeks. They describe your answers, not their causes.</p>'}<a class="text-link" href="#explore">Explore a familiar reaction →</a></section>${latest?`<section class="pattern-section"><h2>Your latest reflection · ${weekLabel(latest.week)}</h2><p class="weekly-note-text">${esc(latest.note||'You made a little space to notice your week.')}</p><div class="actions"><button class="secondary" data-weekly="talk">Talk about this week</button><button class="icon-delete" data-weekly-delete="${esc(latest.week)}">Delete this reflection</button></div><p class="small">“Talk about this week” prepares a message you can review before sending it to Gemini. Weekly answers are not shared automatically.</p></section>`:''}<p class="storage-caption vault-status">${esc(vaultStatus)}</p>`;}
const familiarReaction={id:'familiar',icon:'♡',name:'Explore a familiar reaction',type:'Optional reflection · not trauma detection',time:'At your pace',desc:'Look at a present-day response with curiosity and choice.',steps:[['What happened in a recent moment?','Choose a situation you feel comfortable describing. You do not need to revisit a painful event.'],['What did you notice in yourself?','Describe feelings, body sensations, thoughts or urges without deciding what caused them.'],['What did you do, and what did that do for you?','Consider what helped in the short term and what happened later.'],['What did you need in that moment?','There may be a need, a boundary, a practical problem, or something you are still unsure about.'],['Does this connect to something you already remember?','Optional. Only use experiences you actually remember. No connection is a valid answer; a strong feeling does not prove a forgotten event.'],['What would feel supportive now?','Choose a small present-day step, a boundary, rest, or a person to contact. You can pause and seek professional support if this feels overwhelming.']]};
if(!exercises.some(x=>x.id==='familiar'))exercises.push(familiarReaction);
const weeklyRoute=route;
route=function(){ensureWeekly();const hash=location.hash.slice(1);if(hash==='weekly'||hash==='patterns'){$('#main').innerHTML=hash==='weekly'?weeklyPage():patternsPage();document.body.classList.remove('is-chat');if(hash==='patterns')$('#weekly-metric').onchange=e=>{weeklyMetric=e.target.value;route();};renderCats();}else if(hash==='explore'){$('#main').innerHTML=exercise('familiar');document.body.classList.remove('is-chat');renderCats();}else weeklyRoute();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.weekly==='start'){startWeekly();route();}if(b.dataset.weeklyAnswer!==undefined){weeklyDraft.answers[WEEKLY_QUESTIONS[weeklyIndex].id]=Number(b.dataset.weeklyAnswer);route();}if(b.dataset.weekly==='skip'){delete weeklyDraft.answers[WEEKLY_QUESTIONS[weeklyIndex].id];weeklyIndex=Math.min(WEEKLY_QUESTIONS.length,weeklyIndex+1);route();}if(b.dataset.weekly==='next'){weeklyIndex=Math.min(WEEKLY_QUESTIONS.length,weeklyIndex+1);route();}if(b.dataset.weekly==='back'){if($('#weekly-note'))weeklyDraft.note=$('#weekly-note').value;weeklyIndex=Math.max(0,weeklyIndex-1);route();}if(b.dataset.weekly==='pause'){if($('#weekly-note'))weeklyDraft.note=$('#weekly-note').value;location.hash='chat';}if(b.dataset.weekly==='finish')saveWeeklyReflection();if(b.dataset.weeklyDelete&&confirm('Delete this weekly reflection? Backups and any text already shared with Gemini are unaffected.')){state.weekly=ensureWeekly().filter(r=>r.week!==b.dataset.weeklyDelete);weeklyDraft=null;save();route();}if(b.dataset.weekly==='talk'){const r=ensureWeekly().slice().sort((a,b)=>a.week.localeCompare(b.week)).at(-1);if(r){chatDraft='I want to reflect on my week of '+weekLabel(r.week)+'.\n'+WEEKLY_QUESTIONS.filter(q=>Number.isInteger(r.answers[q.id])).map(q=>q.label+': '+WEEKLY_CHOICES[r.answers[q.id]]).join('\n')+(r.note?'\nMy note: '+r.note:'');location.hash='chat';}}});
// A subtle in-app invitation only. No notification permission or external schedule.
const weeklyChatPage=chatPage;chatPage=function(){const html=weeklyChatPage(),due=!ensureWeekly().some(r=>r.week===localWeekKey());return html.replace('<div class="quiet-chat-actions">','<div class="quiet-chat-actions">'+(due?'<a class="weekly-due" href="#weekly">Your weekly moment '+catSymbol()+'</a>':''));};
route();

const lockWithWeekly=lockAuraVault;lockAuraVault=async function(discard=false){await lockWithWeekly(discard);weeklyDraft=null;weeklyIndex=0;};

const clearWithWeekly=window.auraAfterClear;window.auraAfterClear=function(){weeklyDraft=null;weeklyIndex=0;clearWithWeekly?.();};
